<?php
fscanf(STDIN, "%d %d %d", $hpY, $atkY, $defY);
fscanf(STDIN, "%d %d %d", $hpM, $atkM, $defM);
fscanf(STDIN, "%d %d %d", $h, $a, $d);

$minCost = PHP_INT_MAX;

for ($dATK = 0; $dATK <= 200; $dATK++) {
    $atk = $atkY + $dATK;
    $dmgToMonster = $atk - $defM;
    if ($dmgToMonster <= 0) continue;
    $time = intdiv($hpM + $dmgToMonster - 1, $dmgToMonster);

    for ($dDEF = 0; $dDEF <= 200; $dDEF++) {
        $def = $defY + $dDEF;
        $dmgToYang = $atkM - $def;
        if ($dmgToYang < 0) $dmgToYang = 0;

        $totalDamage = $dmgToYang * $time;
        $neededHP = $totalDamage - $hpY + 1;
        if ($neededHP < 0) $neededHP = 0;

        $cost = $dATK * $a + $dDEF * $d + $neededHP * $h;
        if ($cost < $minCost) {
            $minCost = $cost;
        }
    }
}

echo $minCost . "\n";
